mapper.update:
UPDATE bill
bill_code = #{billCode}, owner_id = #{ownerId}, asset_id = #{assetId}, bill_start_time = #{billStartTime}, bill_end_time = #{billEndTime}, bill_finish_time = #{billFinishTime}, bill_status = #{billStatus}, bill_total = #{billTotal}, bill_paid = #{billPaid}, bill_remark = #{billRemark},
WHERE id = #{id}

mapper.select:
SELECT b.*, u1.user_name AS owner_name, u2.user_name AS creater_name, a.asset_name FROM bill b LEFT JOIN user u1 ON b.owner_id = u1.id LEFT JOIN user u2 ON b.creater_id = u2.id LEFT JOIN asset a ON b.asset_id = a.id
AND b.owner_id = #{ownerId}
AND b.bill_status = #{billStatus}
AND b.bill_code LIKE CONCAT('%', #{billCode}, '%')
ORDER BY b.id ASC
